  "implementation": "def solve(case):
    nodes = case['nodes']
    core_dist = case['core_distance']
    distances = case['distances']

    # Validate nodes unique
    if len(nodes) != len(set(nodes)):
        raise ValueError('Duplicate nodes')

    # Build index mapping for deterministic ordering
    node_to_idx = {node: i for i, node in enumerate(nodes)}
    n = len(nodes)

    # Build edge list: (mutual_reachability, u, v, node_u, node_v)
    edges = []
    seen_pairs = set()
    for entry in distances:
        if len(entry) != 3:
            raise ValueError('Invalid distance entry')
        u, v, dist = entry[0], entry[1], entry[2]
        if u not in node_to_idx or v not in node_to_idx:
            raise ValueError('Unknown node in distance')
        if u == v:
            continue
        # Canonicalize: ensure u < v (by index, then by string for tie)
        ui, vi = node_to_idx[u], node_to_idx[v]
        if ui > vi or (ui == vi and u > v):
            u, v = v, u
            ui, vi = vi, ui
        pair = (u, v)
        if pair in seen_pairs:
            raise ValueError('Duplicate distance entry')
        seen_pairs.add(pair)
        mr = max(core_dist[u], core_dist[v], dist)
        edges.append((mr, u, v, ui, vi))

    # Sort by mutual reachability, then first endpoint, then second
    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    # Union-Find
    parent = list(range(n))
    rank = [0] * n

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    mst_count = 0
    for mr, u, v, ui, vi in edges:
        if union(ui, vi):
            mst_edges.append([u, v, mr])
            total_weight += mr
            mst_count += 1
            if mst_count == n - 1:
                break

    if mst_count != n - 1:
        raise ValueError('Disconnected graph: cannot form MST')

    return {'edges': mst_edges, 'total_weight': total_weight}"
}
